import sys
from itertools import product

def main():
    line = sys.stdin.readline().strip()
    if '=' in line:
        n = int(line.split('=')[1])
    else:
        n = int(line)

    if n == 0:
        print(-1)
        return

    symbols = ['T', '0', '1']
    results = [''.join(p) for p in product(symbols, repeat=n)]
    results.sort()
    for r in results:
        print(r)

if __name__ == "__main__":
    main()
